export type Store=ReturnType<typeof openStore>;
export const activatePolicy=(store:Store,expectedVersion:number,policy:unknown)=>store.activatePolicy(expectedVersion,policy);
export const activateFeed=(store:Store,expectedVersion:number,feed:unknown)=>store.activateFeed(expectedVersion,feed);
