 let fixtureInitialized=false;
 const getRun=(id:string)=>{const row=db.prepare('SELECT * FROM runs WHERE id=?').get(id) as any;if(!row||row.caller!=='developer')throw new ControlError('RUN_NOT_FOUND');return row;};
 const resources=(runId:string)=>{const p=store.getPolicy();const l=db.prepare('SELECT * FROM ledger').get() as any;const rows=db.prepare("SELECT usage,kind,outcome FROM attempts WHERE run_id=? AND kind IN ('actor','checker') AND dispatched=1").all(runId) as any[];let usage:Usage|null=rows.length?{prompt:0,output:0,thought:0,cache:0}:null;for(const row of rows){if(!row.usage){usage=null;break;}const u=JSON.parse(row.usage);if(usage)for(const k of ['prompt','output','thought','cache'] as const)usage[k]+=u[k];}const rates=p.tariffs;const estimatedCost=usage&&[rates.prompt,rates.output,rates.thought,rates.cache].every(v=>v!==null)?(Math.max(0,usage.prompt-usage.cache)*rates.prompt!+usage.output*rates.output!+usage.thought*rates.thought!+usage.cache*rates.cache!)/1e6:null;return {epochId:l.id,creditsReserved:l.credits,creditsLimit:p.limits.credits,callsUsed:l.calls,callsLimit:p.limits.calls,usage,estimatedCost};};
