 function privacy(text:string):string{const p=store.getPolicy();const patterns=[/\bsk-[A-Za-z0-9_-]{12,}\b/g,/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g,/\b(?:\d[ -]?){10,15}\b/g];if(p.controls.privacy==='block'&&patterns.some(re=>re.test(text)))throw new ControlError('PRIVACY_BLOCK');return p.controls.privacy==='redact'?patterns.reduce((s,re)=>s.replace(re,'[REDACTED]'),text):text;}
